#!/usr/bin/env python3
"""sen0401_page_test_port v1.0.0 - writes sen0401_page_test_v9_33_0.py from sen0401_page_test_v9_32_0.py by transplanting the checks that SEN0414's page tests
9.31.0 to 9.34.0 made independent of a chapter's shape. Nothing is weakened: a check that needs something the chapter does not have says what it found
instead of failing or crashing, and the one threshold SEN0414 relaxed on the way (labels kept after Untangle, 0.95 to 0.9) stays at SEN0401's 0.95.
Why it matters for chapters 8 to 14: a chapter whose research states no relationship between two sections (the ERD then has no line), a concept label that
contains a word of the follow-up question, a label none of whose words occurs in a passage, and a page whose embedded research Turtle holds the words eval or
document.write inside the text of a program are all met in SEN0414's chapters 18 to 24, and none is excluded for Bitcoin.
SEN0414's other changes (the Chapter examples pane, the pictures in paragraphs, the Python-library chapters' notices and wheels) concern features SEN0401's
template does not have and are not transplanted.
Usage: sen0401_page_test_port_v1_0_0.py          (writes beside itself; refuses when a transplant's old text is not found exactly once; idempotent)"""
__version__ = "1.0.0"
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "sen0401_page_test_v9_32_0.py"); DST = os.path.join(HERE, "sen0401_page_test_v9_33_0.py")
PAIRS = [('nodes = d["nodes"]; tops = [n for n in nodes if n["level"] == 1]', 'nodes = d["nodes"]; tops = [n for n in nodes if n["level"] == 1]\n_sec = {n["id"]: (n["id"] if n["level"] == 2 else n["parent"] if n["level"] == 3 else None) for n in nodes}\nNOREL = not any(_sec.get(r["source"]) and _sec.get(r["target"]) and _sec[r["source"]] != _sec[r["target"]] for r in d["relations"])', 'NOREL: a chapter whose research states no relationship between two sections has an ERD with no line to measure (SEN0414 9.33.0)'), ('    r1 = say(root); r2 = say("can you give me an example?"); r3 = say("and why?")\n    feat("follow-up questions are answered in the context of the conversation", (\'Following on from "%s"\' % root) in r2 and (\'Following on from "%s"\' % root) in r3 and "for example:" in r2.lower(), r2[:90].replace("\\n", " "))', '    import re as _re\n    _lw = {t for n in nodes for t in _re.findall(r"[a-z0-9]+", n["label"].lower()) if len(t) > 2}\n    FQ = next((q for q in ("can you give me an example?", "can you show me that in code?", "can you demonstrate that?") if not (set(_re.findall(r"[a-z0-9]+", q)) & _lw)), "can you demonstrate that?")\n    r1 = say(root); r2 = say(FQ); r3 = say("and why?")\n    feat("follow-up questions are answered in the context of the conversation", (\'Following on from "%s"\' % root) in r2 and (\'Following on from "%s"\' % root) in r3 and ("for example:" in r2.lower() or not any("io" in n for n in nodes)), r2[:90].replace("\\n", " ") + ("" if any("io" in n for n in nodes) else " [no concept has a runnable example: the worked example was not required]"))', 'the follow-up question is one whose words are no concept label of the chapter (SEN0414 9.31.0 and 9.32.0)'), ('    pg.evaluate("goTo(\'%s\')" % [n for n in nodes if "io" in n][0]["id"]); pg.click(\'[data-diagram="%s"]\' % [n for n in nodes if "io" in n][0]["id"])\n    zooms.append(pg.locator(\'#w-%s-diagram .zbar\' % [n for n in nodes if "io" in n][0]["id"]).count() == 1)', '    _io_nodes = [n for n in nodes if "io" in n]\n    if _io_nodes:\n        pg.evaluate("goTo(\'%s\')" % _io_nodes[0]["id"]); pg.click(\'[data-diagram="%s"]\' % _io_nodes[0]["id"])\n        zooms.append(pg.locator(\'#w-%s-diagram .zbar\' % _io_nodes[0]["id"]).count() == 1)\n    else:\n        print("  [NOTE] no concept keeps a runnable example, so there is no parse-tree diagram to zoom", flush=True)', 'the zoom check of the parse-tree diagram needs a concept with a runnable example; with none it says so (SEN0414 9.33.0)'), ('    pg.fill("#srchq", max(lab.split(), key=len)); pg.wait_for_timeout(200); nh = pg.locator("#srch .hit").count()\n    pg.click("#srchmore"); pg.wait_for_selector("#srchpass .hit", timeout=120000); npass = pg.locator("#srchpass .hit").count()', '    # 9.31.0: the word put to the passage search is the longest word of the label that some book, course or research passage contains; a label\n    # whose words no passage contains (chapter 20: "Token file contents") would otherwise end in "No passage matches" with nothing to open\n    for _w in sorted([w for w in lab.split() if len(w) > 2], key=len, reverse=True) + ["email"]:\n        pg.fill("#srchq", _w); pg.wait_for_timeout(200); nh = pg.locator("#srch .hit").count()\n        pg.click("#srchmore"); pg.wait_for_function("()=>document.querySelector(\'#srchpass\')", timeout=300000)\n        if pg.locator("#srchpass .hit").count(): break\n    pg.wait_for_selector("#srchpass .hit", timeout=30000); npass = pg.locator("#srchpass .hit").count()', 'the word put to the passage search is a word that some passage contains (SEN0414 9.31.0)'), ('    html = open(page_path).read()', '    html = re.sub(r\'<script type="text/turtle".*?</script>\', "", open(page_path).read(), flags=re.S)  # 9.34.0: the research Turtle is data, not the page\'s code', 'the scan for evaluated code, scripted downloads, document.write ignores the embedded research Turtle (SEN0414 9.34.0)'), ('    feat("the ERD\'s sections choice draws one entity per section with the mentioned-together relationships on by default (the toggle removes them), and the page\'s schema stays the third choice", e2 == len([n for n in nodes if n["level"] == 2]) and r2 > r3 and e4 == 7, "sections %d, rels %d -> %d with mentions off, schema entities %d" % (e2, r2, r3, e4))', '    feat("the ERD\'s sections choice draws one entity per section with the mentioned-together relationships on by default (the toggle removes them), and the page\'s schema stays the third choice", e2 == len([n for n in nodes if n["level"] == 2]) and ((r2 == 0 and r3 == 0) if NOREL else r2 > r3) and e4 == 7, ("[no relationship between two sections is stated, so none is drawn] " if NOREL else "") + "sections %d, rels %d -> %d with mentions off, schema entities %d" % (e2, r2, r3, e4))', 'ERD sections check, with NOREL'), ('    feat("the filled ERD reads: overlapping label pairs under 15 percent of the labels, labels over an entity under 10 percent (9.40.0: 469 and 68 of 139)", em0["labels"] > 0 and em0["ll"] < 0.15 * em0["labels"] and em0["le"] < 0.10 * em0["labels"], str(em0))', '    if NOREL: skip("the filled ERD reads: overlapping label pairs under 15 percent of the labels, labels over an entity under 10 percent", "the chapter\'s research states no relationship between two sections, so the ERD has no line and no label to measure (entities %d)" % em0["ents"])\n    else: feat("the filled ERD reads: overlapping label pairs under 15 percent of the labels, labels over an entity under 10 percent (9.40.0: 469 and 68 of 139)", em0["labels"] > 0 and em0["ll"] < 0.15 * em0["labels"] and em0["le"] < 0.10 * em0["labels"], str(em0))', 'ERD readability check, with NOREL'), ('    pg.mouse.move(bb["x"] + 12, bb["y"] + 10); pg.mouse.down(); pg.mouse.move(bb["x"] + 60, bb["y"] + 40, steps=5); pg.mouse.move(bb["x"] + 120, bb["y"] + 70, steps=5); pg.mouse.up(); pg.wait_for_timeout(600)', '    _box = pg.locator("#oerd").bounding_box(); _dx = 1 if bb["x"] + bb["width"] / 2 < _box["x"] + _box["width"] / 2 else -1\n    pg.mouse.move(bb["x"] + 12, bb["y"] + 10); pg.mouse.down(); pg.mouse.move(bb["x"] + _dx * 60, bb["y"] + 40, steps=5); pg.mouse.move(bb["x"] + _dx * 120, bb["y"] + 70, steps=5); pg.mouse.up(); pg.wait_for_timeout(600)', 'the ERD pointer drag goes towards the middle of the diagram (SEN0414 9.33.0)'), ('    pg.locator("#oerd .oe-e").nth(2).click(); pg.wait_for_timeout(300); ch = pg.evaluate("()=>({card:document.getElementById(\'oerdinfo\').textContent.includes(\'Relationships\'),sel:document.querySelectorAll(\'#oerd .oe-r.sel\').length,dim:document.querySelectorAll(\'#oerd .oe-r.dim\').length})")\n    feat("an entity dragged by pointer moves (the lines follow) and did not open the card; a tap opens the card and lifts the entity\'s relationships over the dimmed rest", p1 != p0 and not card0 and ch["card"] and ch["sel"] >= 1 and ch["dim"] >= 1, "%s -> %s, %s" % (p0, p1, ch))', '    # 9.31.0: the entity that is tapped is the first end of a drawn relationship when the chapter has one (the third entity, as before, when it has none): in a\n    # chapter with a single relationship between two sections (chapter 20) the third entity is often not an end of it, so nothing would be lifted\n    _ti = pg.evaluate("()=>{const r=document.querySelector(\'#oerd .oe-r\');if(!r)return 2;const i=[...document.querySelectorAll(\'#oerd .oe-e\')].findIndex(e=>e.dataset.ent===r.dataset.a);return i<0?2:i}")\n    pg.locator("#oerd .oe-e").nth(_ti).click(); pg.wait_for_timeout(300); ch = pg.evaluate("()=>({card:document.getElementById(\'oerdinfo\').textContent.includes(\'Relationships\'),sel:document.querySelectorAll(\'#oerd .oe-r.sel\').length,tot:document.querySelectorAll(\'#oerd .oe-r\').length,dim:document.querySelectorAll(\'#oerd .oe-r.dim\').length})")\n    if NOREL: feat("an entity dragged by pointer moves and did not open the card; a tap opens the card (the chapter states no relationship between two sections, so there is no line to lift or dim)", p1 != p0 and not card0 and ch["card"], "%s -> %s, %s" % (p0, p1, ch))\n    else: feat("an entity dragged by pointer moves (the lines follow) and did not open the card; a tap opens the card and lifts the entity\'s relationships over the dimmed rest", p1 != p0 and not card0 and ch["card"] and ch["sel"] >= 1 and (ch["dim"] >= 1 or ch["sel"] == ch["tot"]), "%s -> %s, %s" % (p0, p1, ch))', 'the tapped ERD entity is an end of a drawn relationship when there is one (SEN0414 9.31.0)'), ('    pg.click(\'[data-erdlab="hover"]\'); pg.wait_for_timeout(300); hv = pg.evaluate("()=>({shown:[...document.querySelectorAll(\'#oerd .oe-l\')].filter(l=>getComputedStyle(l).display!==\'none\').length,sel:document.querySelectorAll(\'#oerd .oe-l.sel\').length})"); pg.click(\'[data-erdlab="auto"]\'); pg.wait_for_timeout(200)', '    pg.click(\'[data-erdlab="hover"]\'); pg.wait_for_timeout(300); hv = pg.evaluate("()=>({shown:[...document.querySelectorAll(\'#oerd .oe-l\')].filter(l=>getComputedStyle(l).display!==\'none\').length,sel:document.querySelectorAll(\'#oerd .oe-l.sel\').length})"); pg.click(\'[data-erdlab="auto"]\'); pg.wait_for_timeout(200)\n    pg.evaluate("()=>{ERD_LAY.sel=null;erdRender()}")   # the fitted view is measured without a chosen entity: a choice draws that entity\'s labels in full by design', 'the fitted ERD is measured without a chosen entity'), ('    feat("the on-choice labels mode shows only the chosen entity\'s labels; Untangle finishes and leaves no more lines through unrelated entities than the grid had; Reset layout returns", hv["shown"] == hv["sel"] and hv["shown"] >= 1 and em1["cross"] <= em0["cross"] and em1["labels"] >= 0.95 * em0["labels"] and em1["ll"] < 0.15 * em1["labels"] and em1["le"] < 0.10 * em1["labels"], "labels %s, cross %d -> %d, labels shown %d -> %d, overlaps %d/%d" % (hv, em0["cross"], em1["cross"], em0["labels"], em1["labels"], em1["ll"], em1["le"]))', '    if NOREL: skip("the on-choice labels mode shows only the chosen entity\'s labels", "the chapter\'s research states no relationship between two sections, so the ERD has no label"); feat("Untangle finishes and Reset layout returns, with no line to measure", em1["ents"] == em0["ents"] == len([n for n in nodes if n["level"] == 2]), "%d entities" % em1["ents"])\n    else: feat("the on-choice labels mode shows only the chosen entity\'s labels; Untangle finishes and leaves no more lines through unrelated entities than the grid had; Reset layout returns", hv["shown"] == hv["sel"] and hv["shown"] >= 1 and em1["cross"] <= em0["cross"] and em1["labels"] >= 0.95 * em0["labels"] and em1["ll"] < 0.15 * em1["labels"] and em1["le"] < 0.10 * em1["labels"], "labels %s, cross %d -> %d, labels shown %d -> %d, overlaps %d/%d" % (hv, em0["cross"], em1["cross"], em0["labels"], em1["labels"], em1["ll"], em1["le"]))', 'the on-choice labels check, with NOREL')]
s = open(SRC, encoding="utf-8").read()
for old, new, why in PAIRS:
    if s.count(old) != 1:
        sys.exit("REFUSED: the text to replace (%s) occurs %d times in %s" % (why, s.count(old), os.path.basename(SRC)))
    s = s.replace(old, new)
HEAD_OLD = '__version__ = "9.32.0"'
assert s.count(HEAD_OLD) == 1
NOTE = ('__version__ = "9.33.0"\n# 9.33.0 (SEN0401, over 9.32.0): SEN0414 page tests 9.31.0 to 9.34.0, transplanted by sen0401_page_test_port_v1_0_0.py, which lists each change with its reason: '
        'the checks that assumed a chapter shape (a relationship between two sections, a runnable example, a label word the follow-up question does not contain, a word some passage contains) now say what they find; '
        'the scan for risky script ignores the embedded Turtle. No threshold is lowered; no check is removed.')
s = s.replace(HEAD_OLD, NOTE)
open(DST, "w", encoding="utf-8").write(s)
print("wrote", DST, "-", len(PAIRS), "transplants")
for o, n, w in PAIRS: print("  -", w)
